/// An attachment that was not kept. Its bytes were never stored.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SkippedAttachment {
    pub filename: String,
    pub size: Option<i64>,
    /// Why it was not kept. `too_many`: the mail had more attachments than the inbox reads. `not_an_invoice`: the judge of the file, or the grouping of the mail, read it as no invoice.
    ///
    /// * `not_an_invoice` - not_an_invoice
    /// * `not_pdf` - not_pdf
    /// * `too_large` - too_large
    /// * `too_many` - too_many
    pub reason: SkippedAttachmentReasonEnum,
}

/// * `not_an_invoice` - not_an_invoice
/// * `not_pdf` - not_pdf
/// * `too_large` - too_large
/// * `too_many` - too_many
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum SkippedAttachmentReasonEnum {
    /// `not_an_invoice`
    #[serde(rename = "not_an_invoice")]
    NotAnInvoice,
    /// `not_pdf`
    #[serde(rename = "not_pdf")]
    NotPdf,
    /// `too_large`
    #[serde(rename = "too_large")]
    TooLarge,
    /// `too_many`
    #[serde(rename = "too_many")]
    TooMany,
    /// A value this version of the client does not know.
    #[serde(untagged)]
    UnknownValue(String),
}

impl SkippedAttachmentReasonEnum {
    /// The value as it goes on the wire.
    pub fn as_str(&self) -> &str {
        match self {
            Self::NotAnInvoice => "not_an_invoice",
            Self::NotPdf => "not_pdf",
            Self::TooLarge => "too_large",
            Self::TooMany => "too_many",
            Self::UnknownValue(value) => value,
        }
    }
}

impl From<&str> for SkippedAttachmentReasonEnum {
    fn from(value: &str) -> Self {
        match value {
            "not_an_invoice" => Self::NotAnInvoice,
            "not_pdf" => Self::NotPdf,
            "too_large" => Self::TooLarge,
            "too_many" => Self::TooMany,
            other => Self::UnknownValue(other.to_owned()),
        }
    }
}

impl From<String> for SkippedAttachmentReasonEnum {
    fn from(value: String) -> Self {
        Self::from(value.as_str())
    }
}

impl fmt::Display for SkippedAttachmentReasonEnum {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

/// A stored file of a company, as the API shows it. The storage name never leaves the server.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct StoredDocument {
    /// The sqid of the file.
    pub id: String,
    pub kind: BooksDocumentKindEnum,
    pub name: String,
    pub content_type: String,
    pub size_bytes: i64,
    pub sha256: String,
    pub received_on: Option<String>,
    /// The ULID of the document in the books.
    pub core_document_id: Option<String>,
    /// The core ULIDs of the bank transactions this file explains.
    pub bank_transaction_ids: Vec<String>,
    /// The sqid of the user who uploaded the file.
    pub uploaded_by: Option<String>,
    /// The mail the file came from, when it came from the invoice inbox; null for an upload.
    pub origin: Option<InboxOrigin>,
    pub created_at: String,
}

